-- United States deep-dive page translations: page fields, stats, cards,
-- lifecycle card + statuses, steps, 2 portals.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Totalmente voluntario, de cuatro esquinas descentralizado', 'Esta página de análisis refleja la orientación disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. El panorama de facturación electrónica de EE. UU. está totalmente impulsado por el mercado, sin ningún mandato en el horizonte — confirme los desarrollos actuales directamente con DBNAlliance o la iniciativa de mejora de pagos de la Reserva Federal antes de tomar decisiones de infraestructura.', 'El enfoque de EE. UU. ha sido impulsado por el mercado desde el principio — un proyecto de eficiencia de pagos nacido de la Reserva Federal, no de una autoridad fiscal cerrando una brecha de IVA (EE. UU. no tiene IVA).', 'No existe un formato obligatorio a nivel federal — la red DBNAlliance tiene su propio estándar, pero gran parte del comercio estadounidense todavía funciona con EDI de décadas de antigüedad.', 'No existe un mandato federal de facturación electrónica B2B en Estados Unidos, y ninguno está actualmente propuesto con un calendario fijo. Hoy existen dos canales genuinamente separados: la red voluntaria DBNAlliance para B2B, y un canal de contratación federal distinto y ya existente (B2G) para quienes venden al gobierno — ambos reales hoy, ninguno obligatorio para el comercio B2B privado.', 'Nada de esto es obligatorio — pero dada la dirección global de la tendencia, la preparación proactiva tiene un beneficio real incluso sin un plazo regulatorio que lo obligue.', 'No existe un marco de sanciones porque no hay ningún mandato que aplicar — toda la postura aquí es estructuralmente diferente de cualquier país de modelo de compensación en este rastreador.' FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Vollständig freiwillig, dezentrales 4-Corner-Modell', 'Diese Länderanalyse spiegelt öffentlich verfügbare Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Die E-Rechnungslandschaft der USA ist vollständig marktgetrieben, ohne ein Mandat am Horizont — bestätigen Sie aktuelle Entwicklungen direkt bei DBNAlliance oder der Zahlungsverbesserungsinitiative der Federal Reserve, bevor Sie Infrastrukturentscheidungen treffen.', 'Der US-Ansatz war von Anfang an marktgeführt — ein Projekt zur Zahlungseffizienz, das aus der Federal Reserve hervorging, nicht aus einer Steuerbehörde, die eine Umsatzsteuerlücke schließt (die USA haben keine Umsatzsteuer).', 'Es gibt kein bundesweit vorgeschriebenes Format — das DBNAlliance-Netzwerk hat seinen eigenen Standard, doch ein Großteil des US-Handels läuft weiterhin über jahrzehntealtes EDI.', 'In den Vereinigten Staaten gibt es kein föderales B2B-E-Rechnungsmandat, und derzeit ist keines mit festem Zeitplan vorgeschlagen. Heute existieren zwei wirklich getrennte Kanäle: das freiwillige DBNAlliance-Netzwerk für B2B und ein eigener, bereits bestehender föderaler Beschaffungskanal (B2G) für alle, die an die Regierung verkaufen — beide heute real, keiner für den privaten B2B-Handel verpflichtend.', 'Nichts davon ist verpflichtend — doch angesichts der globalen Entwicklungsrichtung bringt proaktive Bereitschaft echten Nutzen, auch ohne eine regulatorische Frist, die dazu zwingt.', 'Es gibt kein Sanktionssystem, weil es kein durchzusetzendes Mandat gibt — die gesamte Haltung hier unterscheidet sich strukturell von jedem Clearing-Modell-Land in diesem Tracker.' FROM countries WHERE name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Entièrement volontaire, modèle décentralisé à 4 coins', 'Cette analyse par pays reflète les directives publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Le paysage de la facturation électronique aux États-Unis est entièrement piloté par le marché, sans mandat à l''horizon — confirmez les développements actuels directement auprès de DBNAlliance ou de l''initiative d''amélioration des paiements de la Réserve fédérale avant de prendre des décisions d''infrastructure.', 'L''approche américaine a été pilotée par le marché depuis le début — un projet d''efficacité des paiements né de la Réserve fédérale, et non d''une autorité fiscale comblant un manque à gagner de TVA (les États-Unis n''ont pas de TVA).', 'Il n''existe aucun format imposé au niveau fédéral — le réseau DBNAlliance a sa propre norme, mais une grande partie du commerce américain fonctionne encore avec l''EDI vieux de plusieurs décennies.', 'Il n''existe aucun mandat fédéral de facturation électronique B2B aux États-Unis, et aucun n''est actuellement proposé selon un calendrier fixe. Deux canaux véritablement distincts existent aujourd''hui : le réseau volontaire DBNAlliance pour le B2B, et un canal de passation de marchés fédéral distinct et déjà existant (B2G) pour quiconque vend au gouvernement — tous deux réels aujourd''hui, aucun n''étant obligatoire pour le commerce B2B privé.', 'Rien de tout cela n''est obligatoire — mais compte tenu de l''orientation mondiale, une préparation proactive présente un réel avantage même sans échéance réglementaire l''imposant.', 'Aucun cadre de sanctions n''existe car il n''y a aucun mandat à faire appliquer — toute la posture ici est structurellement différente de chaque pays à modèle de contrôle dans ce tracker.' FROM countries WHERE name_en = 'United States';

