INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Formato de red DBNAlliance', '[["Base", "Facturas basadas en UBL, al estilo Peppol"], ["Estándares", "Abiertos, no propietarios"]]', 'El marco refleja deliberadamente el enfoque técnico de Peppol — una ventaja genuina si su empresa ya tiene experiencia con Peppol por operaciones en la UE o Australia/Nueva Zelanda.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'DBNAlliance-Netzwerkformat', '[["Basis", "UBL-basierte Rechnungen, Peppol-artig"], ["Standards", "Offen, nicht proprietär"]]', 'Das Rahmenwerk spiegelt bewusst den technischen Ansatz von Peppol wider — ein echter Vorteil, wenn Ihr Unternehmen bereits Peppol-Erfahrung aus EU- oder Australien/NZ-Aktivitäten hat.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Format du réseau DBNAlliance', '[["Base", "Factures basées sur UBL, de style Peppol"], ["Normes", "Ouvertes, non propriétaires"]]', 'Le cadre reflète délibérément l''approche technique de Peppol — un avantage réel si votre entreprise a déjà une expérience de Peppol grâce à des opérations dans l''UE ou en Australie/Nouvelle-Zélande.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Lo que realmente domina hoy', '[["Grandes empresas", "EDI heredado y muy extendido, usado durante décadas"], ["Alternativa en crecimiento", "Intercambio basado en la red DBNAlliance"]]', 'No asuma que "facturación electrónica en EE. UU." significa DBNAlliance por defecto — la mayor parte de la facturación estructurada de grandes empresas hoy en día todavía se ejecuta mediante acuerdos EDI bilaterales, no la red más reciente.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Was heute tatsächlich dominiert', '[["Großunternehmen", "Weit verbreitetes Legacy-EDI, seit Jahrzehnten genutzt"], ["Wachsende Alternative", "Netzwerkbasierter Austausch über DBNAlliance"]]', 'Gehen Sie nicht davon aus, dass "E-Rechnungsstellung in den USA" standardmäßig DBNAlliance bedeutet — die meiste strukturierte Rechnungsstellung von Großunternehmen läuft heute noch über bilaterale EDI-Vereinbarungen, nicht über das neuere Netzwerk.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Ce qui domine réellement aujourd''hui', '[["Grandes entreprises", "EDI hérité largement répandu, utilisé depuis des décennies"], ["Alternative en croissance", "Échange basé sur le réseau DBNAlliance"]]', 'Ne présumez pas que « facturation électronique aux États-Unis » signifie DBNAlliance par défaut — la majeure partie de la facturation structurée des grandes entreprises fonctionne encore aujourd''hui via des accords EDI bilatéraux, pas le nouveau réseau.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Sin requisitos de contenido obligatorios', '[["Mandato de formato federal", "Ninguno, para B2B nacional"], ["Participación del IRS", "Ninguna — sin requisito de facturación electrónica de ningún tipo"]]', 'Se trata de una postura genuinamente distinta a la de casi todos los demás países de este rastreador — aquí no hay ninguna autoridad fiscal impulsando la estandarización de formatos en absoluto.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Keine vorgeschriebenen Inhaltsanforderungen', '[["Föderales Formatmandat", "Keines, für inländisches B2B"], ["Beteiligung der IRS", "Keine — überhaupt keine E-Rechnungspflicht"]]', 'Dies ist eine wirklich andere Haltung als in fast jedem anderen Land dieses Trackers — hier treibt überhaupt keine Steuerbehörde die Formatstandardisierung voran.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Aucune exigence de contenu obligatoire', '[["Mandat de format fédéral", "Aucun, pour le B2B national"], ["Implication de l''IRS", "Aucune — aucune exigence de facturation électronique d''aucune sorte"]]', 'Il s''agit d''une posture véritablement différente de celle de presque tous les autres pays de ce tracker — aucune autorité fiscale ne pilote ici la standardisation des formats.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Verificación de la realidad transfronteriza', '[["Si comercia con la UE, México, Brasil, Arabia Saudita, etc.", "Cumplirá sus mandatos independientemente de las reglas de EE. UU."]]', 'Una empresa estadounidense con operaciones internacionales significativas se encontrará con mandatos de facturación electrónica en el extranjero mucho antes de que exista algún equivalente a nivel nacional — planifique en consecuencia en lugar de tratar esto como una cuestión puramente doméstica.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Grenzüberschreitende Realitätsprüfung', '[["Wenn Sie mit der EU, Mexiko, Brasilien, Saudi-Arabien usw. handeln", "Sie werden deren Mandate erfüllen müssen, unabhängig von US-Regeln"]]', 'Ein US-Unternehmen mit nennenswerten internationalen Aktivitäten wird im Ausland lange vor jedem inländischen Äquivalent auf E-Rechnungsmandate stoßen — planen Sie entsprechend, statt dies als rein inländische Frage zu behandeln.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Vérification de la réalité transfrontalière', '[["Si vous commercez avec l''UE, le Mexique, le Brésil, l''Arabie saoudite, etc.", "Vous devrez respecter leurs mandats indépendamment des règles américaines"]]', 'Une entreprise américaine ayant des activités internationales significatives rencontrera des mandats de facturation électronique à l''étranger bien avant qu''un équivalent n''existe sur le plan national — planifiez en conséquence plutôt que de traiter cela comme une question purement nationale.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Gobernanza', '[["DBNAlliance", "Organización sin fines de lucro que gobierna el marco de intercambio"], ["Origen", "Piloto del Mercado de Intercambio de Facturas Electrónicas de la Business Payments Coalition"], ["Respaldo", "Desarrollado con el apoyo de Federal Reserve Financial Services"]]', 'DBNAlliance define estándares, políticas y directrices de entrega electrónica, y ayuda a los proveedores de servicios a conectarse al marco — pero no tiene ninguna autoridad regulatoria ni de recaudación fiscal.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Governance', '[["DBNAlliance", "Gemeinnützige Organisation, die das Austauschrahmenwerk verwaltet"], ["Ursprung", "E-Invoice Exchange Market Pilot der Business Payments Coalition"], ["Unterstützung", "Entwickelt mit Unterstützung von Federal Reserve Financial Services"]]', 'DBNAlliance definiert Standards, Richtlinien und Leitlinien für die elektronische Zustellung und hilft Dienstanbietern, sich mit dem Rahmenwerk zu verbinden — hat jedoch keinerlei regulatorische oder steuerliche Erhebungsbefugnis.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Gouvernance', '[["DBNAlliance", "Organisation à but non lucratif régissant le cadre d''échange"], ["Origine", "Pilote de marché d''échange de factures électroniques de la Business Payments Coalition"], ["Soutien", "Développé avec le soutien de Federal Reserve Financial Services"]]', 'DBNAlliance définit les normes, politiques et lignes directrices de livraison électronique, et aide les fournisseurs de services à se connecter au cadre — mais elle n''a absolument aucune autorité réglementaire ou de collecte fiscale.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Contratación federal — un canal separado', '[["Plataforma", "Plataforma de Procesamiento de Facturas (IPP) de la Oficina del Servicio Fiscal del Tesoro"], ["Alcance", "Solo contratación de agencias federales — no la red DBNAlliance"]]', 'No confunda ambos — si vende a una agencia federal, está tratando con la IPP o una solución aprobada por la agencia, un sistema completamente distinto de la red voluntaria B2B DBNAlliance.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Bundesbeschaffung — ein separater Kanal', '[["Plattform", "Invoice Processing Platform (IPP) des Bureau of the Fiscal Service des Finanzministeriums"], ["Umfang", "Nur Beschaffung durch Bundesbehörden — nicht das DBNAlliance-Netzwerk"]]', 'Verwechseln Sie dies nicht — wenn Sie an eine Bundesbehörde verkaufen, haben Sie es mit der IPP oder einer von der Behörde genehmigten Lösung zu tun, einem völlig eigenständigen System gegenüber dem freiwilligen B2B-DBNAlliance-Netzwerk.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Passation de marchés fédéraux — un canal séparé', '[["Plateforme", "Plateforme de traitement des factures (IPP) du Bureau of the Fiscal Service du Trésor"], ["Portée", "Uniquement la passation de marchés des agences fédérales — pas le réseau DBNAlliance"]]', 'Ne confondez pas les deux — si vous vendez à une agence fédérale, vous avez affaire à l''IPP ou à une solution approuvée par l''agence, un système complètement distinct du réseau volontaire B2B DBNAlliance.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Agnóstico respecto al método de pago', '[["Métodos admitidos", "ACH, transferencia, tarjeta, pagos instantáneos"]]', 'El marco de intercambio admite todos los principales métodos de pago electrónico — está explícitamente diseñado en torno a la eficiencia de pagos, reforzando que se trata de una iniciativa del sector de pagos y no de cumplimiento fiscal.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Zahlungsmethodenunabhängig', '[["Unterstützte Methoden", "ACH, Überweisung, Karte, Sofortzahlungen"]]', 'Das Austauschrahmenwerk unterstützt alle wichtigen elektronischen Zahlungsmethoden — es ist ausdrücklich auf Zahlungseffizienz ausgelegt, was bestätigt, dass es sich um eine Initiative der Zahlungsbranche und nicht um eine Steuerkonformitätsinitiative handelt.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Agnostique quant à la méthode de paiement', '[["Méthodes prises en charge", "ACH, virement, carte, paiements instantanés"]]', 'Le cadre d''échange prend en charge toutes les principales méthodes de paiement électronique — il est explicitement conçu autour de l''efficacité des paiements, renforçant le fait qu''il s''agit d''une initiative du secteur des paiements plutôt que de conformité fiscale.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'es', 'El modelo de cuatro esquinas de DBNAlliance', NULL, 'Un remitente y un destinatario se conectan cada uno una sola vez a su propio proveedor de servicios, y los dos proveedores gestionan el intercambio a través de la red — no se necesita ninguna configuración bilateral por socio comercial, la misma propuesta de valor central que Peppol ofrece en Europa.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'de', 'Das 4-Corner-Modell von DBNAlliance', NULL, 'Ein Absender und ein Empfänger verbinden sich jeweils einmal mit ihrem eigenen Dienstanbieter, und die beiden Anbieter wickeln den Austausch über das Netzwerk ab — keine bilaterale Einrichtung pro Handelspartner erforderlich, dasselbe Kernwertversprechen, das Peppol in Europa bietet.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'United States';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'fr', 'Le modèle à quatre coins de DBNAlliance', NULL, 'Un expéditeur et un destinataire se connectent chacun une fois à leur propre fournisseur de services, et les deux fournisseurs gèrent l''échange à travers le réseau — aucune configuration bilatérale nécessaire par partenaire commercial, la même proposition de valeur fondamentale que Peppol offre en Europe.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'United States';

