INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT dls.id, 'fr', '1. Fournisseur de services de l''expéditeur' FROM deep_dive_lifecycle_statuses_v2 dls JOIN deep_dive_lifecycle_cards dlc ON dlc.id = dls.card_id JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'United States' AND dls.sort_order = 0;
