INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT dls.id, 'fr', '2. Cadre d''échange' FROM deep_dive_lifecycle_statuses_v2 dls JOIN deep_dive_lifecycle_cards dlc ON dlc.id = dls.card_id JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'United States' AND dls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT dls.id, 'es', '3. Proveedor de servicios del destinatario' FROM deep_dive_lifecycle_statuses_v2 dls JOIN deep_dive_lifecycle_cards dlc ON dlc.id = dls.card_id JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'United States' AND dls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT dls.id, 'de', '3. Dienstanbieter des Empfängers' FROM deep_dive_lifecycle_statuses_v2 dls JOIN deep_dive_lifecycle_cards dlc ON dlc.id = dls.card_id JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'United States' AND dls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT dls.id, 'fr', '3. Fournisseur de services du destinataire' FROM deep_dive_lifecycle_statuses_v2 dls JOIN deep_dive_lifecycle_cards dlc ON dlc.id = dls.card_id JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'United States' AND dls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT dls.id, 'es', '4. Destinatario' FROM deep_dive_lifecycle_statuses_v2 dls JOIN deep_dive_lifecycle_cards dlc ON dlc.id = dls.card_id JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'United States' AND dls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT dls.id, 'de', '4. Empfänger' FROM deep_dive_lifecycle_statuses_v2 dls JOIN deep_dive_lifecycle_cards dlc ON dlc.id = dls.card_id JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'United States' AND dls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT dls.id, 'fr', '4. Destinataire' FROM deep_dive_lifecycle_statuses_v2 dls JOIN deep_dive_lifecycle_cards dlc ON dlc.id = dls.card_id JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'United States' AND dls.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Si suministra a agencias federales, confirme su configuración de IPP', 'Esta es la única obligación genuinamente existente aquí — verifique que está conectado a través de la Plataforma de Procesamiento de Facturas del Tesoro o la alternativa aprobada por su agencia.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'United States' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wenn Sie Bundesbehörden beliefern, bestätigen Sie Ihre IPP-Einrichtung', 'Dies ist die einzige tatsächlich bestehende Verpflichtung hier — prüfen Sie, ob Sie über die Invoice Processing Platform des Finanzministeriums oder die von Ihrer Behörde genehmigte Alternative verbunden sind.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'United States' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Si vous approvisionnez des agences fédérales, confirmez votre configuration IPP', 'C''est la seule obligation véritablement existante ici — vérifiez que vous êtes connecté via la plateforme de traitement des factures du Trésor ou l''alternative approuvée par votre agence.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'United States' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Evalúe unirse a la red DBNAlliance', 'Busque un proveedor de servicios miembro o un Punto de Acceso si desea modernizar el intercambio de facturas B2B con sus principales socios comerciales — la participación es totalmente opcional.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'United States' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Erwägen Sie den Beitritt zum DBNAlliance-Netzwerk', 'Suchen Sie nach einem Mitglieds-Dienstanbieter oder Access Point, wenn Sie den B2B-Rechnungsaustausch mit wichtigen Handelspartnern modernisieren möchten — die Teilnahme ist völlig optional.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'United States' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Évaluez l''adhésion au réseau DBNAlliance', 'Recherchez un fournisseur de services membre ou un point d''accès si vous souhaitez moderniser l''échange de factures B2B avec vos principaux partenaires commerciaux — la participation est entièrement facultative.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'United States' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Audite sus relaciones EDI existentes', 'Si ya intercambia facturas estructuradas mediante EDI bilateral, evalúe si el marco abierto de DBNAlliance podría reducir la sobrecarga de mapeo con el tiempo frente a mantener conexiones punto a punto.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'United States' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Prüfen Sie Ihre bestehenden EDI-Beziehungen', 'Wenn Sie bereits strukturierte Rechnungen über bilaterales EDI austauschen, wägen Sie ab, ob das offene Rahmenwerk von DBNAlliance den Mapping-Aufwand langfristig gegenüber der Beibehaltung von Punkt-zu-Punkt-Verbindungen reduzieren könnte.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'United States' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Auditez vos relations EDI existantes', 'Si vous échangez déjà des factures structurées via un EDI bilatéral, évaluez si le cadre ouvert de DBNAlliance pourrait réduire la charge de mappage au fil du temps par rapport au maintien de connexions point à point.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'United States' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme la capacidad UBL de su ERP', 'Si decide unirse a DBNAlliance, compruebe si su software existente puede generar facturas basadas en UBL de forma nativa, o si necesitará un proveedor de Punto de Acceso para cubrir la brecha.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'United States' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie die UBL-Fähigkeit Ihres ERP', 'Wenn Sie sich entscheiden, DBNAlliance beizutreten, prüfen Sie, ob Ihre vorhandene Software nativ UBL-basierte Rechnungen erzeugen kann oder ob Sie einen Access-Point-Anbieter benötigen, um die Lücke zu schließen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'United States' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez la capacité UBL de votre ERP', 'Si vous décidez de rejoindre DBNAlliance, vérifiez si votre logiciel existant peut générer nativement des factures basées sur UBL, ou si vous aurez besoin d''un fournisseur de point d''accès pour combler l''écart.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'United States' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Prepárese para los mandatos internacionales independientemente del estatus nacional', 'Si comercia con la UE, México, Brasil, Arabia Saudita o cualquier otro país con mandato, asegúrese de que sus sistemas puedan producir los formatos que requieren — esta necesidad existe independientemente de lo que ocurra en EE. UU.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'United States' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bereiten Sie sich unabhängig vom Inlandsstatus auf internationale Mandate vor', 'Wenn Sie mit der EU, Mexiko, Brasilien, Saudi-Arabien oder einem anderen Land mit Mandat handeln, stellen Sie sicher, dass Ihre Systeme deren erforderliche Formate erzeugen können — dieser Bedarf besteht unabhängig davon, was in den USA geschieht.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'United States' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Préparez-vous aux mandats internationaux indépendamment du statut national', 'Si vous commercez avec l''UE, le Mexique, le Brésil, l''Arabie saoudite ou tout autre pays imposant un mandat, assurez-vous que vos systèmes peuvent produire leurs formats requis — ce besoin existe indépendamment de ce qui se passe aux États-Unis.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'United States' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Observe a sus socios comerciales, no al regulador', 'Los efectos de red — no los plazos de cumplimiento — son lo que realmente impulsará la adopción de la facturación electrónica en EE. UU. Si un cliente o proveedor importante le pide que se conecte a través de DBNAlliance, ese es el desencadenante práctico para actuar.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'United States' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Beobachten Sie Ihre Handelspartner, nicht den Regulierer', 'Netzwerkeffekte — nicht Compliance-Fristen — werden die tatsächliche Einführung der E-Rechnungsstellung in den USA vorantreiben. Wenn ein wichtiger Kunde oder Lieferant Sie bittet, sich über DBNAlliance zu verbinden, ist das der praktische Auslöser zum Handeln.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'United States' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Surveillez vos partenaires commerciaux, pas le régulateur', 'Les effets de réseau — et non les échéances de conformité — sont ce qui fera réellement progresser l''adoption de la facturation électronique aux États-Unis. Si un client ou fournisseur important vous demande de vous connecter via DBNAlliance, c''est le déclencheur pratique pour agir.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'United States' AND ds.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '💰 Sin sanciones federales por no adopción', NULL, NULL, 'Esto se confirma repetida e inequívocamente en todas las fuentes — no existe un marco de sanciones regulatorias por no adoptar la facturación electrónica en EE. UU. Cualquier consecuencia es puramente comercial, derivada de requisitos contractuales específicos que un socio comercial o una agencia gubernamental pueda imponer.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '💰 Keine föderalen Strafen bei Nichtübernahme', NULL, NULL, 'Dies wird wiederholt und eindeutig in allen Quellen bestätigt — es gibt kein regulatorisches Sanktionssystem für die Nichteinführung der E-Rechnungsstellung in den USA. Etwaige Konsequenzen sind rein kommerzieller Natur und ergeben sich aus spezifischen vertraglichen Anforderungen, die ein Handelspartner oder eine Regierungsbehörde auferlegen könnte.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '💰 Aucune pénalité fédérale pour non-adoption', NULL, NULL, 'Ceci est confirmé de manière répétée et sans ambiguïté par toutes les sources — il n''existe aucun cadre de sanctions réglementaires pour ne pas avoir adopté la facturation électronique aux États-Unis. Toute conséquence est purement commerciale, résultant d''exigences contractuelles spécifiques qu''un partenaire commercial ou une agence gouvernementale pourrait imposer.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🏦 Una historia de pagos, no de impuestos', NULL, NULL, 'El origen de DBNAlliance en la Reserva Federal y la Business Payments Coalition — en lugar del IRS o una autoridad fiscal estatal — es el hecho estructural más importante sobre la facturación electrónica en EE. UU. La motivación es la eficiencia de pagos B2B, no el cierre de una brecha de IVA (EE. UU. no tiene IVA).', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🏦 Eine Zahlungsgeschichte, keine Steuergeschichte', NULL, NULL, 'Der Ursprung von DBNAlliance in der Federal Reserve und der Business Payments Coalition — statt in der IRS oder einer bundesstaatlichen Steuerbehörde — ist die wichtigste strukturelle Tatsache über die E-Rechnungsstellung in den USA. Die Motivation ist B2B-Zahlungseffizienz, nicht das Schließen einer Umsatzsteuerlücke (die USA haben keine Umsatzsteuer).', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🏦 Une histoire de paiements, pas de fiscalité', NULL, NULL, 'L''origine de DBNAlliance dans la Réserve fédérale et la Business Payments Coalition — plutôt que dans l''IRS ou une autorité fiscale d''État — est le fait structurel le plus important concernant la facturation électronique aux États-Unis. La motivation est l''efficacité des paiements B2B, pas la fermeture d''un écart de TVA (les États-Unis n''ont pas de TVA).', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🇨🇦 Una red norteamericana, no puramente nacional', NULL, NULL, 'El marco de DBNAlliance cubre explícitamente tanto EE. UU. como Canadá — vale la pena saberlo si opera a través de la frontera, ya que la misma red voluntaria sirve a ambos mercados.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🇨🇦 Ein nordamerikanisches, nicht rein nationales Netzwerk', NULL, NULL, 'Das Rahmenwerk von DBNAlliance deckt ausdrücklich sowohl die USA als auch Kanada ab — wissenswert, wenn Sie grenzüberschreitend tätig sind, da dasselbe freiwillige Netzwerk beide Märkte bedient.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🇨🇦 Un réseau nord-américain, pas purement national', NULL, NULL, 'Le cadre de DBNAlliance couvre explicitement à la fois les États-Unis et le Canada — utile à savoir si vous opérez de part et d''autre de la frontière, puisque le même réseau volontaire dessert les deux marchés.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🔮 La perspectiva honesta', NULL, NULL, 'Nada de lo que está actualmente en vigor sugiere que un mandato federal estadounidense esté llegando en ningún calendario fijo. Eso podría cambiar — pero la suposición de planificación más segura es que los datos de facturas estructuradas son útiles independientemente de quién los exija, no que un plazo nacional sea inminente.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🔮 Der ehrliche Ausblick', NULL, NULL, 'Nichts, was derzeit in Kraft ist, deutet darauf hin, dass ein US-Bundesmandat mit festem Zeitplan bevorsteht. Das könnte sich ändern — aber die sicherste Planungsannahme ist, dass strukturierte Rechnungsdaten unabhängig davon nützlich sind, wer sie verlangt, nicht dass eine inländische Frist unmittelbar bevorsteht.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🔮 Les perspectives honnêtes', NULL, NULL, 'Rien de ce qui est actuellement en vigueur ne suggère qu''un mandat fédéral américain arrive selon un calendrier fixe. Cela pourrait changer — mais l''hypothèse de planification la plus sûre est que les données de facturation structurées sont utiles indépendamment de qui les exige, et non qu''une échéance nationale soit imminente.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'United States' AND dc.section = 'penalties_related' AND dc.sort_order = 3;

